package org.circus.core;
import java.io.*;
import java.util.*;

/** Raw graphics globals and borrowed cache/pool/name aliases, not Win boot. */
public final class Pc1GraphicsMemoryTests {
 private static int count;private static void check(boolean b,String why){count++;if(!b)throw new AssertionError(why);}private interface Action{void run()throws Exception;}private static void reject(Action a,String text)throws Exception{boolean bad=false;try{a.run();}catch(IOException expected){bad=text==null||expected.getMessage().contains(text);}check(bad,"Reject "+text);}
 private static Pc1DrawMemory.Dword cell(){return new Pc1DrawMemory.Dword(){int v;public int read(){return v;}public void write(int next){v=next;}};}
 private static byte[] wire(Pc1GraphicsMemory m)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();m.save(new DataOutputStream(out));return out.toByteArray();}
 public static int run()throws Exception{
  count=0;Pc1NativeFrame frame=Pc1NativeFrame.zeroBss();Pc1CodeBuffer code=Pc1CodeBuffer.zeroBss();byte[] settings=new byte[Pc1NativeSettings.SIZE];Pc1NativeMemory bus=new Pc1NativeMemory(frame,code,new Pc1NativeMemory.SettingsBytes(){public int read(int p){return settings[p]&255;}public void write(int p,int value){settings[p]=(byte)value;}});Pc1NativeUi ui=new Pc1NativeUi(bus,new Pc1NativeUi.Counters(){final Pc1DrawMemory.Dword a=cell(),b=cell();public Pc1DrawMemory.Dword storyPrefixCount(){return a;}public Pc1DrawMemory.Dword storyFullCount(){return b;}});new Pc1ResourceLiterals(bus);Pc1GraphicsMemory m=new Pc1GraphicsMemory(bus);
  for(int address:new int[]{0x43d418,0x43d420,0x43d424,0x43d430})check(m.readInt(address)==-1,"PE DATA handle−1 "+address);check(m.readInt(0x43028c)==1&&m.readInt(0x94c61c)==0&&m.readInt(0x94c62c)==0&&m.readInt(0x94c630)==0,"actual raw DATA/BSS values, not inferred postbootstrap display flags");check(m.readInt(0x9b9be4)==0&&m.readInt(0x97176c)==0,"uninitialized BSS handles not rewritten to invented−1");
  check(m.readInt(Pc1DrawBatch.PALETTE+4)==0xff0000&&m.readInt(Pc1DrawBatch.PALETTE+8)==0xff00,"actual native G,R,B DATA palette");check(m.readInt(Pc1DrawBatch.PALETTE+63*4)==Pc1NativeUi.MAIN_BUTTONS,"palette63 aliases the preexisting native button pointer");m.writeInt(Pc1DrawBatch.PALETTE+63*4,0x12345678);check(ui.readInt(Pc1NativeUi.BUTTON_POINTER)==0x12345678,"palette alias does not create a second button pointer");ui.writeInt(Pc1NativeUi.BUTTON_POINTER,Pc1NativeUi.MAIN_BUTTONS);m.writeInt(Pc1DrawBatch.SLOT_BASE+9*4,77);check(ui.readInt(0x9553c8)==77,"slot9 directly aliases existing grid configuration owner");
  NativeRgbImage front=NativeRgbImage.zeroed(32,24);Pc1Compositor c=new Pc1Compositor(front);c.installRgb(20,front);final int[] visits={0},reads={0};Pc1GraphicsResources resources=new Pc1GraphicsResources(c,m,new Pc1GraphicsResources.Backend(){public void visitCg(byte[] name){visits[0]++;}public Pc1GraphicsResources.Source readImage(byte[] a,byte[] b,byte[] e){reads[0]++;return null;}});Pc1GlyphCache cache=Pc1GlyphCache.zeroBss();m.bindViews(c,resources,cache);resources.name(20,new byte[]{'t','e','s','t'});int metadata=Pc1GraphicsResources.IMAGE_BASE+20*128,name=metadata+24;
  check(m.readInt(metadata+8)==96&&m.readInt(metadata+12)==32&&m.readInt(metadata+16)==24&&m.readInt(metadata+20)==0,"metadata reads use the actual Compositor image owner");reject(()->m.readInt(metadata),"proven32-bit");m.writeByte(metadata+12,16);check(c.width(20)==16,"raw shape alias writes immediately change the one native record");m.writeByte(metadata+12,32);check(c.width(20)==32,"restoring raw width changes same current typed projection");
  check(resources.load(new byte[]{'t','e','s','t'},0,c)==20&&reads[0]==0,"typed resource cache sees resident-name original backing");m.writeByte(name,'x');check(resources.name(20)[0]=='x'&&resources.load(new byte[]{'t','e','s','t'},0,c)==-1&&visits[0]==1&&reads[0]==1,"native byte name write immediately changes real resource cache behavior");m.writeByte(name+75,0x7f);check(resources.unsignedNameByte(20,75)==0x7f&&resources.name(20).length==4,"name bytes after NUL remain writable stale backing");resources.writeNameByte(20,76,0x66);check(m.read(name+76)==0x66,"resident name direct setter updates the bus view");reject(()->resources.writeNameByte(20,104,1),"neighboring");
  m.writeInt(Pc1GlyphCache.BASE,0x12345678);check(cache.readU8(Pc1GlyphCache.BASE)==0x78,"glyph cache bytes are a view over the supplied canonical cache");m.writeInt(0x949870,-7);m.writeInt(0x949874,512);check(cache.fixedReplacement()==-7&&cache.variableReplacement()==512,"replacement cursor aliases preserve raw DWORD values");cache.variableReplacement(19);check(m.readInt(0x949874)==19,"typed cache mutation visible on native bus without synchronization");
  byte[] saved=wire(m);Pc1GraphicsMemory.Image image=Pc1GraphicsMemory.loadImage(new DataInputStream(new ByteArrayInputStream(saved)));m.writeInt(0x43d418,22);m.writeInt(Pc1DrawBatch.SLOT_BASE,7);m.writeByte(name+75,0x33);cache.fixedReplacement(2);frame.writeU8(0,0x41);m.restore(image);check(Arrays.equals(wire(m),saved),"raw-owned globals roundtrip");check(resources.unsignedNameByte(20,75)==0x33&&cache.fixedReplacement()==2&&frame.readU8(0)==0x41,"global restore does not roll back borrowed names/cache/frame");c.free(20);check(m.readInt(metadata+12)==32&&resources.name(20)[0]=='x',"free retains actual stale dimensions and resident name");
  reject(()->m.bindViews(c,resources,cache),"unique");for(int n:new int[]{0,7,saved.length-1}){byte[] truncated=Arrays.copyOf(saved,n);reject(()->Pc1GraphicsMemory.loadImage(new DataInputStream(new ByteArrayInputStream(truncated))),null);}
  check(m.readInt(0x94f8d8)==c.activeTarget()&&m.readInt(0xbc5f5c)==c.clip().right&&m.readInt(0xbc5f74)==c.baseClip().right,"native target/current/base globals are direct compositor views");m.writeInt(0xbc5f60,7);check(c.clip().left==7&&c.baseClip().left==0,"native current clip byte view does not call clamping setClip or change base");m.writeInt(0xbc5f78,11);check(c.baseClip().left==11&&c.clip().left==7,"native base clip separate canonical field");m.writeInt(0x4304e8,0x12345678);m.writeByte(0x4304e9,0xab);check(c.rawDirty().left==0x1234ab78,"one native dirty byte write changes exactly original DWORD owner");c.fullClip();c.resetDirty();c.fill(3,4,8,9,0xffffff);check(m.readInt(0x4304e8)==3&&m.readInt(0x4304ec)==4&&m.readInt(0x4304f0)==8&&m.readInt(0x4304f4)==9,"pixel kernel dirty union immediately visible on native bus");c.installRgb(21,NativeRgbImage.zeroed(2,2));m.writeInt(0x94f8d8,21);check(c.activeTarget()==21&&c.clip().right==32,"raw active handle write preserves current clip unlike409480");c.target(21);check(m.readInt(0xbc5f5c)==2&&m.readInt(0xbc5f74)==2,"actual409480 resets same bound clip fields to selected dimensions");c.target(0);
  return count;
 }
 public static void main(String[] args)throws Exception{System.out.println("PASS Pc1GraphicsMemoryTests "+run());}
}
